clear; clc; close all;

freqGHz = [0.7 3.5 28];
freqMHz = freqGHz * 1000;
bandName = ["Sub-1 GHz"; "Mid-band"; "mmWave"];

txPowerdBm = 30;
gtDbi = 0;
grDbi = 0;

distanceKm = logspace(log10(0.1),log10(2),200);
distanceAtPointKm = 0.5;

fspl = @(fMHz,dKm) 32.44 + 20*log10(fMHz) + 20*log10(dKm);

lossAtPoint = fspl(freqMHz,distanceAtPointKm);
rxAtPoint = txPowerdBm + gtDbi + grDbi - lossAtPoint;

linkTable = table(bandName,freqGHz(:),lossAtPoint(:),rxAtPoint(:), ...
    'VariableNames',{'Band','Frequency_GHz','FSPL_dB','EstimatedRx_dBm'});

disp(linkTable); %[output:4e5a3a19]

figure; %[output:33750c17]
tiledlayout(1,2); %[output:33750c17]

nexttile; %[output:33750c17]
hold on; %[output:33750c17]
grid on; %[output:33750c17]

for k=1:numel(freqMHz)
    plot(distanceKm,fspl(freqMHz(k),distanceKm),'LineWidth',1.5); %[output:33750c17]
end

set(gca,'XScale','log'); %[output:33750c17]
xlabel('Distance (km)'); %[output:33750c17]
ylabel('Path loss (dB)'); %[output:33750c17]
legend(bandName,'Location','northwest'); %[output:33750c17]
title('Free-Space Path Loss'); %[output:33750c17]

nexttile; %[output:33750c17]
hold on; %[output:33750c17]
grid on; %[output:33750c17]

for k=1:numel(freqMHz)
    rx = txPowerdBm + gtDbi + grDbi - fspl(freqMHz(k),distanceKm);
    plot(distanceKm,rx,'LineWidth',1.5); %[output:33750c17]
end

set(gca,'XScale','log'); %[output:33750c17]
xlabel('Distance (km)'); %[output:33750c17]
ylabel('Estimated received power (dBm)'); %[output:33750c17]
legend(bandName,'Location','southwest'); %[output:33750c17]
title('Illustrative Received Power'); %[output:33750c17]

cellRadiusKm = 0.5;
reuseN = [1 3 7 12];
pathLossExponent = 3.5;

reuseDistance = sqrt(3*reuseN) * cellRadiusKm;
sirLinear = (reuseDistance/cellRadiusKm).^pathLossExponent / 6;
sirDb = 10*log10(sirLinear);

reuseTable = table(reuseN(:),reuseDistance(:),sirDb(:), ...
    'VariableNames',{'ReuseClusterN','ApproxInterfererDistance_km','ApproxSIR_dB'});

disp(reuseTable); %[output:42516e37]

figure; %[output:0ec160c2]
plot(reuseN,sirDb,'o-','LineWidth',1.5); %[output:0ec160c2]
grid on; %[output:0ec160c2]

xlabel('Reuse cluster size N'); %[output:0ec160c2]
ylabel('Approximate SIR (dB)'); %[output:0ec160c2]
title('Simplified Co-Channel SIR versus Reuse Cluster Size'); %[output:0ec160c2]

fprintf('At %.2f km, estimated received powers are:\n',distanceAtPointKm); %[output:52964505]

disp(table(bandName,rxAtPoint(:),'VariableNames',{'Band','Rx_dBm'})); %[output:0a0abf73]

